-- Dữ liệu mẫu cho Feature 002 (quản lý sản phẩm) và Feature 006 (voucher / chương trình ưu đãi).
-- Xuất từ DB local ppswbs_dev ngày 2026-11-08.
--
-- Cách chạy (chọn đúng DB của bạn, script không tự USE):
--   mysql -u <user> -p <ten_db> < ppswbs_backend/scripts/seed-product-voucher-demo.sql
--
-- Chạy lại nhiều lần được: dùng INSERT IGNORE, dòng đã có (trùng id hoặc trùng
-- khoá unique như SKU, mã voucher, tên danh mục) sẽ được giữ nguyên, không ghi đè.
-- Nên chạy trên DB chưa có sản phẩm/voucher; nếu DB đã có dòng trùng id thì
-- dòng con có thể gắn vào dòng sẵn có của bạn.
--
-- Không bao gồm: dữ liệu theo Member (promotion_member_program), giỏ hàng, đơn hàng.
-- Ảnh dùng Cloudinary chung của nhóm nên URL vẫn hiển thị được.
-- Voucher WORKSHOP trỏ tới gói workshop id 2 và chi nhánh id 1 trên DB của bạn.
-- created_by của voucher là id tài khoản trên máy gốc (3, 5).
-- Chi nhánh (US10): file xuất trước khi có tồn kho theo chi nhánh nên không có dòng
-- catalogue_variant_branch_stock; sản phẩm sẽ ở trạng thái "chưa gán chi nhánh" — vào trang chi tiết bấm
-- "Gán chi nhánh" để chuyển số lượng sang chi nhánh trên máy bạn (id chi nhánh khác nhau giữa các máy).

SET NAMES utf8mb4;
SET @OLD_FK_CHECKS = @@FOREIGN_KEY_CHECKS;
SET FOREIGN_KEY_CHECKS = 0;
START TRANSACTION;


COMMIT;
SET FOREIGN_KEY_CHECKS = @OLD_FK_CHECKS;
